import type { Metadata } from "next";
import Breadcrumb from "@/components/header/breadcrumb";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faEnvelope,
  faMapLocationDot,
} from "@fortawesome/free-solid-svg-icons";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title: "Privacy Policy - TravelShop Booking",
  description:
    "Discover our TravelShop Booking Privacy Policy - Your data, your trust. Learn how we safeguard your information for worry-free travel planning.",
  alternates: {
    canonical: "https://travelshopbooking.com/privacy-policy",
  },
};

const prose =
  "tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c] [&_p]:tw-mt-0 [&_p]:tw-mb-4 [&_h2]:tw-text-[19px] [&_h2]:tw-font-bold [&_h2]:tw-text-[#14101c] [&_h2]:tw-mt-8 [&_h2]:tw-mb-3 [&_ul]:tw-my-4 [&_ul]:tw-pl-5 [&_ul]:tw-list-disc [&_li]:tw-mb-1.5 [&_a]:tw-text-[#854ec9] [&_a]:tw-font-semibold [&_strong]:tw-text-[#14101c] [&_i]:tw-text-[#14101c]";

export default function PrivacyPolicyPage() {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Header band */}
      <section className="tw-bg-[#faf9fc] tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[920px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-10 md:tw-py-14">
          <Breadcrumb
            items={[
              { pageTitle: "Privacy Policy", pageUrl: "/privacy-policy" },
            ]}
          />
          <h1 className="tw-mt-4 tw-text-[clamp(28px,4vw,44px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Privacy Policy
          </h1>
        </div>
      </section>

      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[920px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          {/* Who We are */}
          <div className="tw-rounded-2xl tw-bg-[#faf9fc] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 md:tw-p-8">
            <h2 className="tw-text-[19px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-3">
              Who We are?
            </h2>
            <p className="tw-m-0 tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c]">
              TravelShop Booking &amp; Murtis Tour is a brand with Licence
              Number 5291 based in Istanbul Turkey and all contact details are
              provided below. Our profession is to band together the best
              operators with the travelers who are looking for their next
              adventure via our website platform from all around the world with
              the best, and optimum prices. You are at the right place at the
              right time.
            </p>
            <div className="tw-mt-5 tw-space-y-3 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
              <p className="tw-m-0 tw-flex tw-items-start tw-gap-3">
                <FontAwesomeIcon
                  icon={faMapLocationDot}
                  className="tw-mt-1 tw-text-[#854ec9]"
                />
                <span>
                  <strong className="tw-text-[#14101c]">Address: </strong> Head
                  Office: Sirinevler Mah. Adnan Kahveci Bulvarı Karanfil Is
                  Merkezi No: 51 Kat: 4 Daire: 6 - Bahcelievler - Istanbul -
                  Turkey
                </span>
              </p>
              <p className="tw-m-0 tw-flex tw-items-start tw-gap-3">
                <FontAwesomeIcon
                  icon={faEnvelope}
                  className="tw-mt-1 tw-text-[#854ec9]"
                />
                <span>
                  <strong className="tw-text-[#14101c]">Contact: </strong>{" "}
                  <a
                    href="mailto:help@travelshopbooking.com"
                    target="_blank"
                    className="tw-font-semibold tw-text-[#854ec9]"
                  >
                    help@travelshopbooking.com
                  </a>{" "}
                  for any kinds of your questions at any time.
                </span>
              </p>
              <p className="tw-m-0 tw-flex tw-items-start tw-gap-3">
                <svg
                  viewBox="0 0 448 512"
                  width={16}
                  height={16}
                  fill="#16a34a"
                  aria-hidden="true"
                  className="tw-mt-1 tw-shrink-0"
                >
                  <path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-32.6-16.3-54-29.1-75.5-66-5.7-9.8 5.7-9.1 16.3-30.3 1.8-3.7 .9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 35.2 15.2 49 16.5 66.6 13.9 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z" />
                </svg>
                <span>
                  <strong className="tw-text-[#14101c]">
                    Call us via Whatsapp:{" "}
                  </strong>{" "}
                  <a
                    href="tel:+905495405430"
                    className="tw-font-semibold tw-text-[#854ec9]"
                  >
                    +905495405430
                  </a>
                </span>
              </p>
            </div>
          </div>

          {/* Image breakout 1 */}
          <div className="tw-mt-10 tw-grid tw-grid-cols-1 lg:tw-grid-cols-[320px_1fr] tw-gap-8 tw-items-center">
            <img
              src="/images/privacy1.webp"
              alt="legal1"
              loading="lazy"
              className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
            />
            <div className={prose}>
              <h2 className="!tw-mt-0">What is the Privacy Policy?</h2>
              <p>
                Like all other digital markets, we collect our users&rsquo; data
                and process it during their bookings, and other additional
                services such as your name, surname, contact, payment details,
                and else. However, we believe in the importance of personal
                privacy, and to prevent all kinds of abuse and misuse cases we
                endeavor to treat all our customers&rsquo; data in a secure
                mode. Since May 25, 2018, all the individuals&rsquo; data are
                under the protection of the{" "}
                <a
                  href="https://gdpr-info.eu/"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  General Data Protection Regulatıon (GDPR)
                </a>{" "}
                which was governed by the European Union. TravelShop Booking is
                process customers&rsquo; data according to this regulation and
                announces all the innovations from this page.
              </p>
              <h2>How and Which Data Do We Gather?</h2>
              <p>
                When you visit our website, call us, fill out a form from the
                web, email us, or book any kind of tour from our system your
                data is collected. Your full name, email, age, address, birth
                date, passport details, and else you provide are collected too
                when you book any tour or other services via our marketplace.
                However, your credit card data is collected only when you are on
                the payment step and secure via &quot;
                <a
                  href="https://www.cloudflare.com/learning/"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Cloudflare Letsencrypt SSL Certificate
                </a>
                &quot; which means that any of our staff can not reach or screen
                it at any time for any reason.
              </p>
            </div>
          </div>

          {/* Prose continued */}
          <div className={`tw-mt-10 ${prose}`}>
            <h2 className="!tw-mt-0">When &amp; How Your Data Used for?</h2>
            <p>
              When you decide to go for a holiday and visit our website we need
              to know and contact you both to provide the information you asked
              for and to accomplish our obligations which are:
            </p>
            <ul>
              <li>To provide you quote</li>
              <li>
                To discuss the tour you consider and the booking you have made
              </li>
              <li>To send you the requested information</li>
              <li>
                To send you the e-marketing brochures, if you submitted them to
                the mailing list
              </li>
              <li>To book your tour</li>
              <li>To receive feedback about our services</li>
              <li>
                Notifying you of the changes and arrangements to your booking
              </li>
            </ul>
            <p>
              Please note that we never rent or sell any kind of your data for
              the 3rd parties, we only forward the necessary part of it to the
              operation team to bu sure your tour and all other arrangements are
              done.
            </p>
            <p>
              Although not very often we will notify you about news, discounts,
              campaigns, and new destinations via email. However, you can
              unsubscribe from the mailing list whenever you want by clicking
              the &ldquo;unsubscribe&rdquo; button at the bottom of the mail we
              send.
            </p>
          </div>

          {/* Image breakout 2 */}
          <div className="tw-mt-10 tw-grid tw-grid-cols-1 lg:tw-grid-cols-[1fr_320px] tw-gap-8 tw-items-center">
            <div className={prose}>
              <h2 className="!tw-mt-0">How Long is Data Retention?</h2>
              <p>
                TravelShop Booking is a Turkey-based company and is subject to
                Turkish laws. Legally, your financial information must be kept
                on our files for five (5) years, and other kinds of data such as
                email, and phone numbers are retained for three (3) years.
                Please keep in mind that TravelShop Booking always takes
                precautions and uses the newest ways of data protection and
                periodically deletes/removes expired data.
              </p>
              <h2>About Blogs, Images, Photographs…</h2>
              <p>
                We share the photographs, reviews, and blogs that are taken
                during the tour by our guides or sent by you after the tours.
                These are generally group photos taken at the end of the tour by
                our guide, the ones sent by you after the tour or the forms
                asked to populate them via email. During the tours, we verbally
                ask your permission to both take photos and send forms via
                email. However, if you do not agree with any of these, during or
                after the tour the process ends, just say it. We use that data
                on our social media accounts and blog by tagging you.
              </p>
              <p>
                In addition to this, if you mention one of our tours and share a
                photograph on your blog and notify us about this, we first ask
                your permission and then share it through our blog and social
                media accounts by quoting your account.
              </p>
              <p>
                However, if you change your mind, have questions, or wish to
                send new photos or blogs, just write to us at{" "}
                <a
                  href="mailto:help@travelshopbooking.com"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  help@travelshopbooking.com
                </a>
                , so we can remove or add them.
              </p>
            </div>
            <img
              src="/images/privacy2.webp"
              alt="legal1"
              loading="lazy"
              className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
            />
          </div>

          {/* Prose continued */}
          <div className={`tw-mt-10 ${prose}`}>
            <h2 className="!tw-mt-0">What About Mail Marketing</h2>
            <p>
              With your permission, although not very often, we inform you
              about;
            </p>
            <ul>
              <li>our new tours,</li>
              <li>destinations,</li>
              <li>discounts,</li>
              <li>news,</li>
              <li>to remind deadline of your credits,</li>
              <li>the new tours that you might be interested in,</li>
              <li>campaigns,</li>
            </ul>
            <p>via email on the mail marketing process.</p>
            <p>
              This process starts with asking you to submit our mailing list,
              and if you submit your name and email, it will be added to the
              mailing list. All the emails that we send you include an
              &quot;unsubscribe&quot; button at the end of the page, so you can
              unsubscribe whenever you want. TravelShop Booking respects the
              customer&rsquo;s privacy and never shares, sells, or rents any of
              its customers&rsquo; names, phone numbers, addresses, or emails
              with any third party. All this information is secure on our
              servers and protected.
            </p>
            <p>
              <i>So who can access your data?</i> Only TravelShop Booking and
              our developers can access it. Nevertheless, they are legally
              responsible for securing your data and privacy too. However, if
              you share your information with a tour operator or any other site,
              we do not accept any responsibility for their privacy practices.
            </p>
            <h2>What about POP-UPS?</h2>
            <p>
              While you are browsing our website you will see a small number of
              pop-ups and they store data too. However, TravelShop Booking
              organizes these pop-ups internally, not in connection with the
              external services, so all the data coming via pop-ups is stored
              and secure only in our servers.
            </p>
            <h2>How do We Use Google And Cookies?</h2>
            <p>
              Like pop-ups, TravelShop Booking uses a small number of{" "}
              <a
                href="https://www.aboutcookies.org/"
                target="_blank"
                rel="noopener noreferrer"
              >
                cookies
              </a>{" "}
              on our pages. Also, we use Google remarketing practices and Google
              Analytics for advertising purposes. You can edit or turn off your
              preferences{" "}
              <a
                href="https://adssettings.google.com/"
                target="_blank"
                rel="noopener noreferrer"
              >
                here
              </a>{" "}
              and opt-out from or learn more about Google Analytics{" "}
              <a
                href="https://tools.google.com/dlpage/gaoptout/?hl=en"
                target="_blank"
                rel="noopener noreferrer"
              >
                here
              </a>
              .
            </p>
            {/* Meta App Review: mesajlaşma verisinin kullanımı + veri silme talimatı bu iki bölümde.
                Meta uygulamasındaki "Data deletion instructions URL" #data-deletion çapasına bakar. */}
            <h2 id="messaging" className="tw-scroll-mt-28">
              Messages You Send Us on WhatsApp, Instagram and Messenger
            </h2>
            <p>
              When you write to our WhatsApp number, our Instagram account or our
              Facebook Page, we receive your message together with the name,
              username or phone number that the platform shares with businesses.
              We use these messages only to answer you and to arrange the tour
              or service you ask about. If you ask for a tour, we may pass the
              details of your request (your name, contact details and what you
              asked for) to the local agency that operates that tour, so they
              can prepare your offer.
            </p>
            <p>
              Your messages are stored on our own secure servers and are only
              accessible to our team. We do not use them for advertising and we
              never sell or rent them to third parties. They are kept under the
              same retention rules described above, unless you ask us to delete
              them.
            </p>
            <h2 id="data-deletion" className="tw-scroll-mt-28">
              How Can You Delete Your Data?
            </h2>
            <p>
              You can ask us to delete your personal data at any time, including
              the messages you sent us on WhatsApp, Instagram or Messenger. Email{" "}
              <a
                href="mailto:help@travelshopbooking.com?subject=Data%20deletion%20request"
                target="_blank"
                rel="noopener noreferrer"
              >
                help@travelshopbooking.com
              </a>{" "}
              with the subject &quot;Data deletion request&quot; and tell us how
              you contacted us (your email address, phone number, Instagram
              username or Facebook name), so we can find your data.
            </p>
            <p>
              We will confirm your request and delete your data within 30 days.
              The only exception is information we are legally required to keep,
              such as the financial records of a completed booking; we keep that
              only for the period required by law and delete it afterwards.
            </p>
            <p>
              Please do not hesitate to contact any kind of questions at{" "}
              <a
                href="mailto:help@travelshopbooking.com"
                target="_blank"
                rel="noopener noreferrer"
              >
                help@travelshopbooking.com
              </a>
            </p>
          </div>
        </div>
      </section>
    </main>
  );
}
